mapper.select:
SELECT review_id, user_id, facility_id, content, rating, created_at, updated_at
FROM review
WHERE review_id = #{reviewId}

SELECT review_id, user_id, facility_id, content, rating, created_at, updated_at
FROM review
WHERE facility_id = #{facilityId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT review_id, user_id, facility_id, content, rating, created_at, updated_at
FROM review
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT AVG(rating)
FROM review
WHERE facility_id = #{facilityId}

SELECT COUNT(*)
FROM review
WHERE facility_id = #{facilityId}

SELECT review_id, user_id, facility_id, content, rating, created_at, updated_at
FROM review
WHERE user_id = #{userId} AND facility_id = #{facilityId}
